void smartHubSystem_init(SmartHubSystem* handle)
{
	sc_integer i;
	
	for (i = 0; i < SMARTHUBSYSTEM_MAX_ORTHOGONAL_STATES; ++i)
	{
		handle->stateConfVector[i] = SmartHubSystem_last_state;
	}
	
				
	clear_in_events(handle);
	clear_internal_events(handle);
	
	sc_observable_init(&handle->iface.HubON);
	sc_observable_init(&handle->iface.HubOFF);
	sc_observable_init(&handle->ifaceHUB.AllSystemsOFF);
	sc_observable_init(&handle->ifaceHUB.AllSystemsON);
	sc_observable_init(&handle->ifaceHUB.emergency_toggle);
	sc_observable_init(&handle->ifaceSmartTV.isON);
	sc_observable_init(&handle->ifaceSmartTV.isOFF);
	sc_observable_init(&handle->ifaceSmartLightsHUB.isON);
	sc_observable_init(&handle->ifaceSmartLightsHUB.isOFF);
	sc_observable_init(&handle->ifaceSmartMicrowave.isON);
	sc_observable_init(&handle->ifaceSmartMicrowave.isOFF);
	sc_observable_init(&handle->ifaceSmartGarageDoor.isON);
	sc_observable_init(&handle->ifaceSmartGarageDoor.isOFF);
	
	/* Default init sequence for statechart SmartHubSystem */
	smartHubSystem_set_totalSystemsON(handle, 0);
	smartHubSystem_set_allSystemsOn(handle, bool_false);
	smartHubSystem_set_powerManager(handle, sc_null);
	smartHubSystem_set_sTV(handle, sc_null);
	smartHubSystem_set_sL_HUB(handle, sc_null);
	smartHubSystem_set_sF(handle, sc_null);
	smartHubSystem_set_sMW(handle, sc_null);
	smartHubSystem_set_sGD(handle, sc_null);
	smartHubSystem_set_wiFi(handle, sc_null);
	smartHubSystem_HUB_set_totalDevices(handle, 0);
	smartHubSystem_HUB_set_emergency(handle, bool_false);
	smartHubSystem_Network_set_sF_connection(handle, bool_false);
	smartHubSystem_Network_set_sTV_connection(handle, bool_false);
	smartHubSystem_Network_set_sL_connection(handle, bool_false);
	smartHubSystem_Network_set_sMW_connection(handle, bool_false);
	smartHubSystem_Network_set_sGD_connection(handle, bool_false);
	smartHubSystem_Power_set_index(handle, 0);
	smartHubSystem_Power_set_total(handle, 0);
	smartHubSystem_Power_set_threshold(handle, 90);
	smartHubSystem_Power_set_thresholdReached(handle, bool_false);
	smartHubSystem_SmartFire_set_alarm_isOn(handle, bool_false);
	smartHubSystem_SmartFire_set_kWh(handle, 20);
	smartHubSystem_SmartTV_set_on(handle, bool_false);
	smartHubSystem_SmartTV_set_kWh(handle, 50);
	smartHubSystem_SmartLightsHUB_set_on(handle, bool_false);
	smartHubSystem_SmartLightsHUB_set_kWh(handle, 15);
	smartHubSystem_SmartMicrowave_set_on(handle, bool_false);
	smartHubSystem_SmartMicrowave_set_kWh(handle, 10);
	smartHubSystem_SmartGarageDoor_set_on(handle, bool_false);
	smartHubSystem_SmartGarageDoor_set_kWh(handle, 10);
	
	handle->isExecuting = bool_false;
	smarthubsystem_eventqueue_init(&handle->internal_event_queue, handle->internal_buffer, SMARTHUBSYSTEM_INTERNAL_EVENTQUEUE_BUFFERSIZE);
	smarthubsystem_eventqueue_init(&handle->in_event_queue, handle->in_buffer, SMARTHUBSYSTEM_IN_EVENTQUEUE_BUFFERSIZE);
}

void smartHubSystem_enter(SmartHubSystem* handle)
{
	/* Activates the state machine. */
	if (handle->isExecuting == bool_true)
	{ 
		return;
	} 
	handle->isExecuting = bool_true;
	/* Default enter sequence for statechart SmartHubSystem */
	enseq__SmartHubSystem__default(handle);
	handle->isExecuting = bool_false;
}

void smartHubSystem_exit(SmartHubSystem* handle)
{
	/* Deactivates the state machine. */
	if (handle->isExecuting == bool_true)
	{ 
		return;
	} 
	handle->isExecuting = bool_true;
	/* Default exit sequence for statechart SmartHubSystem */
	exseq__SmartHubSystem_(handle);
	handle->stateConfVector[0] = SmartHubSystem_last_state;
	handle->stateConfVectorPosition = 0;
	handle->isExecuting = bool_false;
}

/*!
Can be used by the client code to trigger a run to completion step without raising an event.
*/
void smartHubSystem_trigger_without_event(SmartHubSystem* handle) {
	run_cycle(handle);
}


sc_boolean smartHubSystem_is_active(const SmartHubSystem* handle)
{
	sc_boolean result = bool_false;
	sc_integer i;
	
	for(i = 0; i < SMARTHUBSYSTEM_MAX_ORTHOGONAL_STATES; i++)
	{
		result = result || handle->stateConfVector[i] != SmartHubSystem_last_state;
	}
	
	return result;
}

/* 
 * Always returns 'false' since this state machine can never become final.
 */
sc_boolean smartHubSystem_is_final(const SmartHubSystem* handle)
{
	SC_UNUSED(handle);
	return bool_false;
}

void smartHubSystem_raise_time_event(SmartHubSystem* handle, sc_eventid evid)
{
	if ( ((sc_intptr_t)evid) >= ((sc_intptr_t)&(handle->timeEvents))
		&&  ((sc_intptr_t)evid) < ((sc_intptr_t)&(handle->timeEvents)) + (unsigned)sizeof(SmartHubSystemTimeEvents))
	{
		smartHubSystem_add_event_to_queue(&(handle->in_event_queue), smartHubSystem_get_timed_event_name(handle, evid));
		run_cycle(handle);
	}
}

