static void smarthubsystem_eventqueue_init(smarthubsystem_eventqueue * eq, smarthubsystem_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer smarthubsystem_eventqueue_size(smarthubsystem_eventqueue * eq)
{
	return eq->size;
}

static smarthubsystem_event smarthubsystem_eventqueue_pop(smarthubsystem_eventqueue * eq)
{
	smarthubsystem_event event;
	if(smarthubsystem_eventqueue_size(eq) <= 0) {
		smarthubsystem_event_init(&event, SmartHubSystem_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean smarthubsystem_eventqueue_push(smarthubsystem_eventqueue * eq, smarthubsystem_event ev)
{
	if(smarthubsystem_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void smarthubsystem_event_init(smarthubsystem_event * ev, SmartHubSystemEventID name)
{
	ev->name = name;
}

static void smartHubSystem_add_event_to_queue(smarthubsystem_eventqueue * eq, SmartHubSystemEventID name)
{
	smarthubsystem_event event;
	smarthubsystem_event_init(&event, name);
	smarthubsystem_eventqueue_push(eq, event);
}

