static smarthubsystem_event smartHubSystem_get_next_event(SmartHubSystem* handle)
{
	smarthubsystem_event next_event;
	smarthubsystem_event_init(&next_event, SmartHubSystem_invalid_event);
	if(smarthubsystem_eventqueue_size(&(handle->internal_event_queue)) > 0) {
		next_event = smarthubsystem_eventqueue_pop(&(handle->internal_event_queue));
	}
	else if(smarthubsystem_eventqueue_size(&(handle->in_event_queue)) > 0) {
		next_event = smarthubsystem_eventqueue_pop(&(handle->in_event_queue));
	}
	return next_event;
}

static sc_boolean smartHubSystem_dispatch_next_event(SmartHubSystem* handle)
{
	smarthubsystem_event nextEvent;
	nextEvent = smartHubSystem_get_next_event(handle);
	return smartHubSystem_dispatch_event(handle, &nextEvent);
}

